import unittest
from decimal import Decimal

from billing import invoice_amount


class InvoiceAmountTests(unittest.TestCase):
    def test_valid_amounts_are_decimal_values_with_two_places(self):
        self.assertEqual(invoice_amount("0"), Decimal("0.00"))
        self.assertEqual(invoice_amount(" 12.5 "), Decimal("12.50"))
        self.assertEqual(invoice_amount("999999999999999999999999.99"), Decimal("999999999999999999999999.99"))

    def test_invalid_formats_are_rejected(self):
        for value in ("", "   ", "-1", "+1", "1.", ".5", "1.000", "1e2", "1,000", "abc"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    invoice_amount(value)

    def test_non_string_values_are_rejected(self):
        for value in (None, 1, 1.2):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    invoice_amount(value)


if __name__ == "__main__":
    unittest.main()
